// node src/state/recipeUrls.v3.selfcheck.mjs
// #2324 — kc-r/3 and kc-recipe/3: a link or a text recipe carries the WHOLE scene. Pins:
//   · v1/v2 links and texts decode exactly as before (frozen fixtures generated by the old decoder on main)
//   · a dressed scene -> link -> decode -> applyScene gives a scene that deep-equals the source
//   · a link is read against ITS epoch's layout defaults, never the live ones (audit F4)
//   · custom assets travel only when they fit 8 KB, else the link says how many are missing (audit F5)
//   · a hostile link is refused whole and cannot fill memory
//   · the 3 replay-golden scenes, fully dressed, encode to <= 2,000 URL characters (audit F3)
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { useStore } from './store.js';
import { sceneOf, DOC_FIELD_CLASS } from './projectDocument.js';
import {
  encodeRecipeUrl,
  decodeRecipeUrl,
  parseBootHash,
  buildShareHref,
  extractRecipePayload,
  fitCustomAssets,
  describeDroppedAssets,
  RECIPE_CUSTOM_ASSET_BUDGET,
  RECIPE_MAX_INFLATED_BYTES,
  RECIPE_URL_PREFIX_3,
} from './recipeUrls.js';
import { encodeRecipe, parseRecipe, recipeToProjectDoc, recipeApplyOptions, recipeFieldsFromKept } from './recipes.js';
import { recipeFieldsFromState } from './recipeLive.js';
import { SCENE_BLOCK_KEYS, CODEC_OWN_SCENE_KEYS, pickSceneBlock } from './recipeSceneKeys.js';
import { LAYOUT_DEFAULTS_EPOCH, defaultsForEpoch } from '../data/recipeDefaults/index.js';
import { DEFAULT_LAYOUT_PARAMS, normalizeLayoutParams } from '../data/layout-modes.js';
import { WORLD_STOCK } from '../data/world.js';
import { LIGHT_DEFAULT } from '../data/light.js';
import { ASSETS } from '../data/assets/index.js';
import { autoAttachPoints } from '../engine/autoAttach.js';
import { assembleConstruct } from '../engine/constructAssembler.js';
import { assembleCreature } from '../engine/creatureAssembler.js';
import { sanitizeOverlay } from '../assets/overlay.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const S = () => useStore.getState();
const clone = (v) => JSON.parse(JSON.stringify(v));
let checks = 0;
const ok = (name) => console.log(`  ok ${++checks} — ${name}`);

// ── 1. v1/v2 stay readable, exactly as before ─────────────────────────────────────────────────────────────────
// recipeLinks.v12.fixtures.json was generated by the ORIGINAL (pre-v3) decoder and parser on main: the new reader
// must return the same recipes, byte for byte. The one intended change is the version error naming kc-r/3 too.
{
  const fx = JSON.parse(readFileSync(join(HERE, 'recipeLinks.v12.fixtures.json'), 'utf8'));
  const names = Object.keys(fx.links);
  assert.ok(
    names.length >= 8,
    'the fixtures cover v1, v1 with overrides, a bare v1, a v2 stack, and the hostile cases',
  );
  assert.ok(
    names.some((n) => fx.links[n].startsWith('kc-r/2.') && fx.linkDecoded[n].ok),
    'a real v2 stack link is among them',
  );
  for (const name of names) {
    const got = clone(await decodeRecipeUrl(fx.links[name]));
    const want = clone(fx.linkDecoded[name]);
    if (want.error) want.error = want.error.replace('kc-r/1 and kc-r/2.', 'kc-r/1, kc-r/2 and kc-r/3.');
    assert.deepEqual(got, want, `link fixture "${name}" decodes as it always did`);
  }
  for (const name of Object.keys(fx.texts)) {
    assert.deepEqual(
      clone(parseRecipe(fx.texts[name])),
      clone(fx.textParsed[name]),
      `text fixture "${name}" parses as it always did`,
    );
  }
  ok(
    `${names.length} frozen v1/v2 links and ${Object.keys(fx.texts).length} texts read exactly as the old reader read them`,
  );
}

// ── 2. The scene block is the document's scene, nothing left out ────────────────────────────────────────────────
{
  const scene = Object.keys(DOC_FIELD_CLASS).filter((k) => DOC_FIELD_CLASS[k] === 'scene');
  const covered = [...SCENE_BLOCK_KEYS, ...CODEC_OWN_SCENE_KEYS];
  assert.deepEqual(
    [...covered].sort(),
    [...scene].sort(),
    "every scene key of the project document is either in the scene block or one of the recipe's own fields. A scene key added to DOC_FIELD_CLASS must be listed in state/recipeSceneKeys.js, or links silently drop it",
  );
  assert.equal(new Set(covered).size, covered.length, 'no key is listed twice');
  // teeth: the same comparison fails when a key is missing from the list
  const missing = [...SCENE_BLOCK_KEYS.slice(1), ...CODEC_OWN_SCENE_KEYS];
  assert.notDeepEqual([...missing].sort(), [...scene].sort(), 'a scene key missing from the list is caught');
  ok("SCENE_BLOCK_KEYS + the recipe's own fields are exactly the scene keys of DOC_FIELD_CLASS");
}

// ── a fully dressed scene, built from valid parts (sanitizers drop anything invalid, so junk would prove nothing) ─
const byId = new Map(ASSETS.map((a) => [a.id, a]));
const VOCAB = ['geo_circle_01', 'geo_square_01', 'geo_halfcircle_01', 'geo_quartercircle_01'].map((id) => ({
  id,
  points: autoAttachPoints(byId.get(id).svg),
}));
const marked = (asset) =>
  autoAttachPoints(asset.svg).map((p, i) => ({ ...p, role: i === 0 ? 'H' : i <= 2 ? 'L' : undefined }));
const SMALL_ASSET = {
  id: 'user:t0000001',
  name: 'dot',
  svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10"><circle cx="5" cy="5" r="4"/></svg>',
};
assert.equal(sanitizeOverlay([SMALL_ASSET]).length, 1, 'the custom-asset fixture is one the sanitizer keeps');

/** Dress the store: every scene key a recipe can carry, set to a real value. `over` overrides parts. */
function dress(over = {}) {
  useStore.setState(useStore.getInitialState(), true);
  const construct = assembleConstruct({ style: 'bauhaus', vocabulary: VOCAB, seed: 7 });
  const creature = assembleCreature({ assetId: ASSETS[0].id, points: marked(ASSETS[0]), seed: 3 });
  assert.ok(construct && creature, 'the dressing assembles a construct and a creature');
  useStore.setState({
    seed: 0xbeef,
    seedOffsets: { spatial: 3, color: 0, asset: 0, noise: -2 },
    paletteId: 'praystation',
    paletteOverrides: { swatches: ['#112233', '#445566'], bg: '#000000' },
    layoutParams: normalizeLayoutParams({
      ...DEFAULT_LAYOUT_PARAMS,
      mode: 'grid',
      count: 300,
      jitter: 11,
      kinemePattern: 'SWELL',
    }),
    enabledAssets: { org_blob_01: true, geo_circle_01: true, rad_rings_01: false, creature: true },
    world: clone(WORLD_STOCK.marks[0]),
    light: { ...LIGHT_DEFAULT, x: 300, y: 90, intensity: 0.6 },
    canvasW: 1080,
    canvasH: 1920,
    canvasPresetId: 'story',
    constructRecords: [construct],
    constructLead: true,
    shapeShelf: [{ style: 'bauhaus', asset: 'geo_circle_01' }],
    creatureRecords: [creature],
    customAssets: sanitizeOverlay([SMALL_ASSET]),
    ...over,
  });
  S().addPatternLayer('GLYPH');
  S().addFxLayer();
  S().addMathLayer();
  S().setActiveLayer(S().layers.find((l) => l.type === 'content').id);
  return S();
}

// ── 3. Dressed scene -> link -> fresh receiver -> applyScene == the source scene ──────────────────────────────
{
  dress();
  const source = clone(sceneOf(S()));
  for (const k of [
    'world',
    'light',
    'constructRecords',
    'creatureRecords',
    'shapeShelf',
    'customAssets',
    'canvasW',
    'enabledAssets',
    'layers',
  ]) {
    assert.ok(source[k] !== undefined, `the source scene really carries ${k}`);
  }
  const link = await encodeRecipeUrl(recipeFieldsFromState(S()), { buildId: 'abc1234' });
  assert.ok(link.startsWith(RECIPE_URL_PREFIX_3));
  assert.ok(/^kc-r\/3\.[A-Za-z0-9_-]+$/.test(link), 'pure base64url after the prefix');

  // a receiver with a different scene AND its own rig
  useStore.setState(useStore.getInitialState(), true);
  useStore.setState({
    projectTitle: 'THEIR SET',
    canvasFps: 30,
    audioRoutes: [{ marker: 'theirs' }],
    seed: 1,
    constructLead: false,
  });
  const rigBefore = clone({ title: S().projectTitle, fps: S().canvasFps, routes: S().audioRoutes });
  const dec = await decodeRecipeUrl(link);
  assert.ok(dec.ok, dec.error);
  assert.equal(dec.recipe.version, 'kc-r/3');
  assert.equal(dec.recipe.buildId, 'abc1234');
  assert.equal(dec.recipe.layoutEpoch, LAYOUT_DEFAULTS_EPOCH);
  assert.deepEqual(recipeApplyOptions(dec.recipe), { replaceAll: true });
  S().applyScene(
    { ...recipeToProjectDoc(dec.recipe), paletteOverrides: dec.recipe.paletteOverrides ?? null },
    recipeApplyOptions(dec.recipe),
  );
  assert.deepEqual(clone(sceneOf(S())), source, "the receiver's scene deep-equals the sender's");
  assert.deepEqual(
    clone({ title: S().projectTitle, fps: S().canvasFps, routes: S().audioRoutes }),
    rigBefore,
    'the rig is untouched',
  );
  assert.equal(S().historyUndoStack.length, 1, 'one undo step');
  ok(
    'a dressed scene (palette+overrides, layout, world, light, constructs, creature, shelf, canvas, cast, custom asset, layer stack) survives link -> apply exactly',
  );

  // the same scene as v3 TEXT
  const text = encodeRecipe(recipeFieldsFromState(dress()));
  assert.equal(text.split('\n')[0], 'kc-recipe/3');
  const want = clone(sceneOf(S()));
  const parsed = parseRecipe(text);
  assert.ok(parsed.ok, parsed.error);
  useStore.setState(useStore.getInitialState(), true);
  S().applyScene(
    { ...recipeToProjectDoc(parsed.recipe), paletteOverrides: parsed.recipe.paletteOverrides ?? null },
    recipeApplyOptions(parsed.recipe),
  );
  // the text carries the active track's scene and the stack; its layout is the full live layout
  const got = clone(sceneOf(S()));
  for (const k of SCENE_BLOCK_KEYS) assert.deepEqual(got[k], want[k], `text round trip: ${k}`);
  for (const k of ['seed', 'seedOffsets', 'paletteId', 'paletteOverrides'])
    assert.deepEqual(got[k], want[k], `text round trip: ${k}`);
  assert.deepEqual(got.layoutParams, want.layoutParams, 'text round trip: layout');
  ok('kc-recipe/3 text carries the same scene (one JSON line per scene-block key, sorted)');
}

// ── 3b. A v3 link REPLACES the scene; a v1/v2 link still MERGES (Matt: "Old: keep. v3: clear") ───────────────────
{
  const bare = await encodeRecipeUrl({ seed: 4, paletteId: 'praystation', layoutParams: { ...DEFAULT_LAYOUT_PARAMS } });
  const old = 'kc-r/1.' + Buffer.from(JSON.stringify({ v: 1, s: 4, p: 'praystation' })).toString('base64url');
  const standing = () => {
    dress();
    useStore.setState({ projectTitle: 'THEIR SET' });
  };
  const apply = async (link) => {
    const dec = await decodeRecipeUrl(link);
    assert.ok(dec.ok, dec.error);
    S().applyScene(
      { ...recipeToProjectDoc(dec.recipe), paletteOverrides: dec.recipe.paletteOverrides ?? null },
      recipeApplyOptions(dec.recipe),
    );
  };
  standing();
  const castBefore = clone(S().enabledAssets);
  await apply(bare);
  assert.equal(S().world, null, 'v3: a world the link does not carry is cleared');
  assert.equal(S().constructLead, false);
  assert.deepEqual(S().constructRecords, []);
  assert.deepEqual(S().shapeShelf, []);
  assert.deepEqual(S().enabledAssets, castBefore, "v3: the receiver's cast is never blanked by a link that lists none");
  assert.equal(S().projectTitle, 'THEIR SET', 'v3: the rig is never touched');
  standing();
  const worldBefore = clone(S().world);
  await apply(old);
  assert.deepEqual(S().world, worldBefore, 'v1: an old link leaves the world alone');
  assert.equal(S().constructLead, true);
  assert.equal(S().constructRecords.length, 1);
  ok('a v3 link replaces the scene (never the rig, never the cast); a v1 link still merges');
}

// ── 4. Text shape: hand-editable lines, sorted ──────────────────────────────────────────────────────────────────
{
  const text = encodeRecipe({
    seed: 5,
    paletteId: 'praystation',
    paletteOverrides: { bg: '#000000' },
    layoutParams: { mode: 'grid' },
    scene: { world: { chapter: 'house' }, light: { x: 1 }, canvasW: 800 },
  });
  const lines = text.split('\n');
  assert.deepEqual(lines.slice(0, 4), [
    'kc-recipe/3',
    'seed: 0x5',
    'palette: praystation',
    'paletteOverrides: {"bg":"#000000"}',
  ]);
  const tail = lines.filter((l) => /^(canvasW|light|world):/.test(l));
  assert.deepEqual(
    tail.map((l) => l.split(':')[0]),
    ['canvasW', 'light', 'world'],
    'scene lines sorted by key',
  );
  assert.equal(parseRecipe(text).recipe.scene.world.chapter, 'house');
  for (const bad of ['kc-recipe/3\nseed: 0x1\nworld: {oops', 'kc-recipe/3\nseed: 0x1\npaletteOverrides: [1]']) {
    assert.equal(parseRecipe(bad).ok, false, `refuses: ${bad.split('\n')[2]}`);
  }
  assert.equal(parseRecipe('kc-recipe/2\nseed: 0x1\nworld: {}').ok, false, 'a /2 recipe has no scene lines');
  assert.equal(parseRecipe('kc-recipe/3\nseed: 0x1\nprojectTitle: "x"').ok, false, 'a rig key is not a recipe key');
  ok('kc-recipe/3 lines are hand-editable and sorted; damaged or foreign lines are refused in plain language');
}

// ── 5. A link is read against ITS epoch, not the live defaults (audit F4) ───────────────────────────────────────
{
  const epoch = defaultsForEpoch(LAYOUT_DEFAULTS_EPOCH);
  const fields = { seed: 1, paletteId: 'praystation', layoutParams: { ...epoch, count: 321 } };
  const link = await encodeRecipeUrl(fields);
  const live = DEFAULT_LAYOUT_PARAMS.jitter;
  try {
    DEFAULT_LAYOUT_PARAMS.jitter = live + 50; // a future default change, as if epoch 2 had not been cut
    const dec = await decodeRecipeUrl(link);
    assert.equal(dec.recipe.layoutParams.jitter, epoch.jitter, 'the link still means the jitter it was made with');
    assert.equal(dec.recipe.layoutParams.count, 321);
    const v1 = await decodeRecipeUrl('kc-r/1.' + Buffer.from(JSON.stringify({ v: 1, s: 1 })).toString('base64url'));
    assert.equal(
      v1.recipe.layoutParams.jitter,
      live + 50,
      'a v1 link keeps its old, live-defaults behaviour (unchanged by v3)',
    );
  } finally {
    DEFAULT_LAYOUT_PARAMS.jitter = live;
  }
  // and the delta is small: a default layout writes no `l` at all
  const bare = await encodeRecipeUrl({ seed: 1, layoutParams: { ...epoch } });
  const back = await decodeRecipeUrl(bare);
  assert.deepEqual(back.recipe.layoutParams, epoch);
  const { inflate } = await inflated(bare);
  assert.equal(inflate.l, undefined, 'a default layout adds nothing');
  assert.equal(inflate.d, LAYOUT_DEFAULTS_EPOCH);
  // a link from a newer epoch is refused, naming the fix
  const future = await forge({ v: 3, d: LAYOUT_DEFAULTS_EPOCH + 1, s: 1 });
  const r = await decodeRecipeUrl(future);
  assert.equal(r.ok, false);
  assert.match(r.error, /newer build/);
  ok('layout is a delta against the frozen epoch the link names; live default drift cannot change an old link');
}

// ── 6. Custom assets: embedded when they fit 8 KB deflated, else dropped with a count (audit F5) ──────────────────
{
  const noise = (n, seed) => {
    let x = seed;
    let out = '';
    for (let i = 0; i < n; i++) {
      x = (Math.imul(x, 1664525) + 1013904223) >>> 0;
      out += 'abcdefghijklmnopqrstuvwxyz0123456789'[x % 36];
    }
    return out;
  };
  const small = [{ ...SMALL_ASSET }];
  const big = [0, 1].map((i) => ({
    id: `user:t000000${i + 2}`,
    name: `big${i}`,
    svg: `<svg viewBox="0 0 1 1">${noise(9000, i + 7)}</svg>`,
  }));
  assert.equal((await fitCustomAssets({ customAssets: small })).dropped, 0);
  const dropped = await fitCustomAssets({ customAssets: big, world: { chapter: 'house' } });
  assert.equal(dropped.dropped, 2);
  assert.equal(dropped.scene.customAssets, undefined);
  assert.deepEqual(dropped.scene.world, { chapter: 'house' }, 'only the assets are dropped');

  const fits = await decodeRecipeUrl(await encodeRecipeUrl({ seed: 1, scene: { customAssets: small } }));
  assert.deepEqual(fits.recipe.scene.customAssets, small);
  assert.equal(fits.recipe.droppedCustomAssets, 0);
  assert.equal(describeDroppedAssets(0), null);

  const lost = await decodeRecipeUrl(
    await encodeRecipeUrl({ seed: 1, scene: { customAssets: big, world: { chapter: 'house' } } }),
  );
  assert.equal(lost.recipe.scene.customAssets, undefined);
  assert.deepEqual(lost.recipe.scene.world, { chapter: 'house' });
  assert.equal(lost.recipe.droppedCustomAssets, 2);
  assert.equal(describeDroppedAssets(lost.recipe.droppedCustomAssets), '2 custom assets not in link');
  assert.equal(describeDroppedAssets(1), '1 custom asset not in link');
  assert.ok(RECIPE_CUSTOM_ASSET_BUDGET === 8192);
  ok(
    'custom assets travel when they deflate to <= 8 KB; above that all are left out and the link says "2 custom assets not in link"',
  );
}

// ── 7. Hostile links are refused whole, and cannot fill memory ──────────────────────────────────────────────────
{
  const refuse = async (link, why) => {
    const r = await decodeRecipeUrl(link);
    assert.equal(r.ok, false, why);
    assert.equal(typeof r.error, 'string');
    return r;
  };
  await refuse('kc-r/3.', 'empty payload');
  await refuse('kc-r/3.A', 'impossible length');
  await refuse('kc-r/3.!!!!', 'bad alphabet');
  await refuse('kc-r/3.' + Buffer.from('not deflate at all').toString('base64url'), 'not a deflate stream');
  await refuse(await forge('plain string'), 'not an object');
  await refuse(await forge({ v: 3, d: 1 }), 'no seed');
  await refuse(await forge({ v: 3, s: 1 }), 'no epoch');
  await refuse(await forge({ v: 3, d: 1, s: 1, x: [1] }), 'scene block is an array');
  await refuse(await forge({ v: 3, d: 1, s: 1, l: 'x' }), 'layout is not an object');
  await refuse(await forge({ v: 3, d: 1, s: 1, k: { l: 'x' } }), 'stack is malformed');
  await refuse(await forge({ v: 2, d: 1, s: 1 }), 'a /3 link claiming v2');
  await refuse(await forge({ v: 4, d: 1, s: 1 }), 'unknown payload version');
  const bomb = await forgeRaw(new Uint8Array(RECIPE_MAX_INFLATED_BYTES * 8).fill(0x20));
  const r = await refuse(bomb, 'a decompression bomb');
  assert.match(r.error, /unpacks to far more/, 'named for what it is');
  // an `x` of foreign keys: only scene keys are read, rig keys never reach applyScene
  const sneaky = await decodeRecipeUrl(
    await forge({
      v: 3,
      d: 1,
      s: 1,
      x: {
        world: { chapter: 'house' },
        projectTitle: 'PWN',
        audioRoutes: [1],
        midiMap: { a: 1 },
        kits: [1],
        __proto__: { polluted: 1 },
      },
    }),
  );
  assert.deepEqual(Object.keys(sneaky.recipe.scene), ['world'], 'only scene-block keys are read');
  assert.equal({}.polluted, undefined);
  const capped = await decodeRecipeUrl(await forge({ v: 3, d: 1, s: 1, n: 1e12 }));
  assert.ok(capped.recipe.droppedCustomAssets <= 9999);
  ok('malformed, truncated, wrong-version, foreign-key and decompression-bomb links are all refused or ignored safely');
}

// ── 8. Boot parse, paste extraction, defaults ─────────────────────────────────────────────────────────────────────
{
  const link = await encodeRecipeUrl({ seed: 9, paletteId: 'praystation', layoutParams: {} });
  const href = buildShareHref(link, 'https://example.test/Kinetic_Curator/');
  assert.equal(extractRecipePayload(`see ${href} thanks`), link, 'a pasted v3 link is found in text');
  const boot = await parseBootHash(new URL(href).hash);
  assert.equal(boot.status, 'ok');
  assert.equal(boot.recipe.seed, 9);
  assert.equal((await parseBootHash('#r=kc-r/3.AAAA')).status, 'bad');
  assert.equal((await parseBootHash('')).status, 'none');
  const dflt = (await decodeRecipeUrl(await encodeRecipeUrl({ seed: 1 }))).recipe.buildId;
  assert.ok(
    typeof dflt === 'string' && dflt.length > 0,
    'a link always names its build (the version when there is no stamp)',
  );
  assert.deepEqual(recipeApplyOptions({ version: 'kc-r/2' }), { replaceAll: false }, 'old formats still merge');
  assert.deepEqual(recipeApplyOptions({ version: 'kc-recipe/1' }), { replaceAll: false });
  assert.deepEqual(recipeApplyOptions({ version: 'kc-recipe/3' }), { replaceAll: true });
  ok('a pasted or booted v3 link is found and read; every link names its build; only v3 replaces the scene');
}

// ── 9. LENGTH BUDGET: the 3 replay-golden scenes, fully dressed, fit 2,000 URL characters (audit F3) ──────────────
// The goldens (engine/kernel/replay/goldens) are kernel recipes, not store scenes: each scene takes its golden's seed,
// point count and canvas, plus the one shared full dressing above. Custom assets keep their own 8 KB budget and are
// the one thing outside this one (an asset is the user's artwork, not scene structure).
{
  const GOLD = join(HERE, '../engine/kernel/replay/goldens');
  const BASE = 'https://neuralio444.github.io/Kinetic_Curator/';
  const results = [];
  for (const name of ['audio-driven', 'field-heavy', 'placement-heavy']) {
    const g = JSON.parse(readFileSync(join(GOLD, `${name}.json`), 'utf8'));
    dress({
      seed: g.seed >>> 0,
      customAssets: [],
      canvasW: g.recipe.canvasW,
      canvasH: g.recipe.canvasH,
      canvasPresetId: 'custom',
      layoutParams: normalizeLayoutParams({
        ...DEFAULT_LAYOUT_PARAMS,
        mode: 'grid',
        count: g.recipe.count,
        jitter: 11,
        kinemePattern: 'SWELL',
      }),
    });
    const fields = recipeFieldsFromState(S());
    assert.ok(Object.keys(fields.scene).length >= 8, `${name}: the scene is really dressed`);
    // #2325 — the budget holds WITH the frame-0 proof (`f`, 16 hex) on the link.
    const link = await encodeRecipeUrl({ ...fields, frame0Hash: '276009aa90fb8c42' }, { buildId: 'abc1234' });
    const href = buildShareHref(link, BASE);
    results.push(`${name} ${href.length}`);
    assert.ok(href.length <= 2000, `${name}: ${href.length} URL characters (budget 2000)`);
    // it is the whole story, not a trimmed one: it decodes to the same scene
    const dec = await decodeRecipeUrl(link);
    assert.ok(dec.ok);
    assert.equal(dec.recipe.droppedCustomAssets, 0);
    assert.equal(dec.recipe.seed, g.seed >>> 0);
  }
  ok(`3 dressed golden scenes encode within 2,000 URL characters (${results.join(', ')})`);
}

console.log(`recipeUrls.v3.selfcheck: OK (${checks} checks)`);

// ── helpers ──────────────────────────────────────────────────────────────────────────────────────────────────
async function forgeRaw(bytes) {
  const cs = new CompressionStream('deflate-raw');
  const w = cs.writable.getWriter();
  w.write(bytes).catch(() => {});
  w.close().catch(() => {});
  const out = new Uint8Array(await new Response(cs.readable).arrayBuffer());
  return 'kc-r/3.' + Buffer.from(out).toString('base64url');
}
async function forge(obj) {
  return forgeRaw(new TextEncoder().encode(JSON.stringify(obj)));
}
async function inflated(link) {
  const ds = new DecompressionStream('deflate-raw');
  const w = ds.writable.getWriter();
  w.write(Buffer.from(link.slice(RECIPE_URL_PREFIX_3.length), 'base64url')).catch(() => {});
  w.close().catch(() => {});
  const text = await new Response(ds.readable).text();
  return { inflate: JSON.parse(text) };
}
